import{Ct as e,ct as t,lt as n,q as r}from"./chunks/framework.BVmwMUcr.js";var i=JSON.parse(`{"title":"Nearby","description":"An overview of places near SCUT Guangzhou International Campus","frontmatter":{"lang":"en-US","title":"Nearby","description":"An overview of places near SCUT Guangzhou International Campus","llm_translated":true},"headers":[],"relativePath":"en/infra/gzic/nearby.md","filePath":"en/infra/gzic/nearby.md","lastUpdated":1791510705000}`),a={name:`en/infra/gzic/nearby.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /en/infra/gzic/nearby.md for this page in Markdown format</div><h1 id="around-gzic" tabindex="-1">Around GZIC <a class="header-anchor" href="#around-gzic" aria-label="Permalink to “Around GZIC”">​</a></h1><h2 id="dining" tabindex="-1">Dining <a class="header-anchor" href="#dining" aria-label="Permalink to “Dining”">​</a></h2><ul><li><strong>Around the Southwest Gate</strong>: A few minutes&#39; walk down the alley from the Southwest Gate brings you to the <strong>Nancun shopping area</strong>, with plenty of restaurants along the way and inside the area</li><li><strong>Around the North Main Gate</strong>: Turn right outside the North Main Gate to find Shaxian Delicacies and other restaurants</li><li><strong>Along the way to Banqiao Station</strong>: B Ji Fish Congee (open in the evenings only) and other shops</li></ul><h2 id="daily-shopping" tabindex="-1">Daily Shopping <a class="header-anchor" href="#daily-shopping" aria-label="Permalink to “Daily Shopping”">​</a></h2><p>The Nancun shopping area has supermarkets and fruit shops, enough to meet everyday needs. There is no wet market nearby for now.</p><h2 id="rentals" tabindex="-1">Rentals <a class="header-anchor" href="#rentals" aria-label="Permalink to “Rentals”">​</a></h2><p>Students with relevant experience are welcome to add rental information for the area around the International Campus.</p><h2 id="transit-connections" tabindex="-1">Transit Connections <a class="header-anchor" href="#transit-connections" aria-label="Permalink to “Transit Connections”">​</a></h2><ul><li><strong>Banqiao Station (Line 7)</strong>: relatively close, reachable on foot or by shared bike</li><li><strong>Xinzao Station (Line 4)</strong>: reachable by shared bike, but farther away</li></ul><h2 id="leisure-entertainment" tabindex="-1">Leisure &amp; Entertainment <a class="header-anchor" href="#leisure-entertainment" aria-label="Permalink to “Leisure &amp; Entertainment”">​</a></h2><p>The Nancun shopping area has KTV, a cinema, and other facilities. Entertainment options around the International Campus are limited; for more choices, head into the city.</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};